def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separates groups of nested parentheses into separate strings.

    :param paren_string: A string containing multiple groups of nested parentheses.
    :return: A list of strings, where each string is a separate group of balanced parentheses.
    """
    result = []
    stack = []
    current_group = []

    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            stack.append(char)
            current_group.append(char)
        elif char == ')':
            if stack:
                stack.pop()
                current_group.append(char)
                if not stack:
                    result.append(''.join(current_group))
                    current_group = []
            else:
                raise ValueError("Unmatched closing parenthesis found")

    if stack:
        raise ValueError("Unmatched opening parenthesis found")

    return result

