    :param N: int - The length of the number string.
    :param K: int - The number of multiplication signs to insert.
    :return: int - The maximum product obtained.
    """
    if not num_str or N <= 0 or K <= 0:
        return 0

    if K >= N - 1:
        return int(num_str)

    def split_number(num_str, splits):
        if splits == 0:
            return [int(num_str)]
        max_product = 0
        for i in range(1, len(num_str)):
            left = int(num_str[:i])
            right = split_number(num_str[i:], splits - 1)
            for r in right:
                max_product = max(max_product, left * r)
        return [max_product]

    return split_number(num_str, K)[0]

def max_product(num_str: str, N: int, K: int) -> int:
    if N <= 0 or K <= 0 or K >= N:
        return 0

    def split_and_multiply(parts):
        product = 1
        for part in parts:
            if part:
                product *= int(part)
        return product

    def backtrack(start, parts):
        if len(parts) == K + 1:
            return split_and_multiply(parts)

        max_prod = 0
        for i in range(start + 1, N - (K - len(parts)) + 1):
            new_parts = parts + [num_str[start:i]]
            max_prod = max(max_prod, backtrack(i, new_parts))

        return max_prod

    return backtrack(0, [])

def max_product(num_str: str, N: int, K: int) -> int:
