    digits = [int(d) for d in num_str]

    # Base case: if there's only one division, return the number itself
    if K == 1:
        return int(num_str)

    # Initialize a DP table to store the maximum product up to each position with a given number of multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # Base case: product of an empty string is considered 1

    for i in range(1, N + 1):
        for k in range(K + 1):
            for j in range(i, 0, -1):
                current_number = int(num_str[j-1:i])
