def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
    M (int): The number of rows in the classroom.
    N (int): The number of columns in the classroom.
    K (int): The number of horizontal aisles to add.
    L (int): The number of vertical aisles to add.
    D (int): The number of chatting pairs in the classroom.
    chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
    (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    from collections import defaultdict

    def count_separated_pairs(row, col):
        separated = set()
        for (x1, y1, x2, y2) in chatting_pairs:
            if (x1 == row or x2 == row) and min(y1, y2) < col < max(y1, y2):
                separated.add((x1, y1, x2, y2))
            if (y1 == col or y2 == col) and min(x1, x2) < row < max(x1, x2):
                separated.add((x1, y1, x2, y2))
        return len(separated)

    # Count the separated pairs for each potential aisle position
    row_counts = defaultdict(int)
    col_counts = defaultdict(int)

    for col in range(1, N):
        for (x1, y1, x2, y2) in chatting_pairs:
            if min(y1, y2) < col < max(y1, y2):
                row_counts[min(x1, x2) + (max(x1, x2) - min(x1, x2)) // 2] += 1

    for row in range(1, M):
        for (x1, y1, x2, y2) in chatting_pairs:
            if min(x1, x2) < row < max(x1, x2):
                col_counts[min(y1, y2) + (max(y1, y2) - min(y1, y2)) // 2] += 1

    # Select the top K and L positions
    best_rows = sorted(row_counts.keys(), key=lambda x: -row_counts[x])[:K]
    best_cols = sorted(col_counts.keys(), key=lambda x: -col_counts[x])[:L]

    return (' '.join(map(str, best_rows)), ' '.join(map(str, best_cols)))

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] represents the number of ways to reach student j after i passes
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1  # Starting point

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    return dp[m][0] % (10**9 + 7)

