    beads = beads + beads[:-1]  # Duplicate the beads list to simulate circular nature
    dp = [[[0] * n for _ in range(n)] for _ in range(2 * n)]

    for length in range(2, n + 1):
        for i in range(n):
            j = i + length - 1
            if j >= 2 * n:
                break
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return max(dp[i][i + n - 1] for i in range(n))

def max_energy(beads):
    if len(beads) < 3:
        return 0

    n = len(beads)
    beads = beads + beads  # Extend the list to handle circular nature

    # dp[i][j] will store the maximum energy released for beads[i] to beads[j] (inclusive)
    dp = [[0] * (2 * n) for _ in range(2 * n)]

    # Chain length
    for length in range(2, n + 1):
        for i in range(n * 2 - length + 1):
            j = i + length - 1
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    # Find the maximum energy for merging a chain of length n in the extended list
    max_energy = 0
    for i in range(n):
        max_energy = max(max_energy, dp[i][i + n - 1])

    return max_energy

