def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x, start):
        if k == 1:
            return 1 if n >= x else 0
        count = 0
        for i in range(start, (n // k) + 1):
            if i >= x:
                count += helper(n - i, k - 1, x, i)
        return count

    if n < k * x:
        return 0
    return helper(n, k, x, x)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last <= 0:
        return 0
    if last in memo:
        return memo[last]
    if last == n:
        count = 1
        for i in range(1, (last // 2) + 1):
            count += count_sequences(n, i, memo)
    else:
        count = 0
        for i in range(1, (last // 2) + 1):
            count += count_sequences(n, i, memo)
    memo[last] = count
    return count

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last < 1 or last > n:
        return 0
    if last == 1:
        return 1
    if last in memo:
        return memo[last]

    count = 1  # Counting the sequence consisting of 'last' itself
    for new_last in range(1, last // 2 + 1):
        count += count_sequences(n, new_last, memo)

    memo[last] = count
    return count

