def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a mapping of rules for quick lookup
    rule_map = defaultdict(set)
    for x, y in rules:
        rule_map[x].add(y)

    # Initialize BFS
    queue = deque([n])
    visited = set([n])

    while queue:
        current = queue.popleft()
        current_str = str(current)

        # Generate all possible transformations
        for i, char in enumerate(current_str):
            digit = int(char)
            if digit in rule_map:
                for new_digit in rule_map[digit]:
                    new_number_str = current_str[:i] + str(new_digit) + current_str[i+1:]
                    new_number = int(new_number_str)
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

