def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Convert number to a list of digits
    def to_digits(num):
        return [int(d) for d in str(num)]

    # Convert list of digits back to number
    def to_number(digits):
        return int(''.join(map(str, digits)))

    # Create a mapping of transformation rules for quick lookup
    transformation_map = defaultdict(set)
    for x, y in rules:
        transformation_map[x].add(y)

    # Initialize BFS
    queue = deque([n])
    visited = set([n])

    # Perform BFS
    while queue:
        current_number = queue.popleft()
        digits = to_digits(current_number)

        # Try each digit in the current number
        for i in range(len(digits)):
            current_digit = digits[i]
            if current_digit in transformation_map:
                for new_digit in transformation_map[current_digit]:
                    # Create a new number with the digit transformed
                    new_digits = digits[:]
                    new_digits[i] = new_digit
                    new_number = to_number(new_digits)

                    # Add the new number to the queue if not visited
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, participant_statements in statements.items():
        is_liar = participant in liar_count
        for statement in participant_statements:
            if statement in days_of_week:
                continue
            if statement.startswith("I am guilty."):
                if (participant == scenario and is_liar) or (participant != scenario and not is_liar):
                    return False
            elif statement.endswith("is guilty."):
                suspect = statement.split()[0]
                if (suspect == scenario and not is_liar) or (suspect != scenario and is_liar):
                    return False
            elif statement.endswith("is not guilty."):
                suspect = statement.split()[0]
                if (suspect == scenario and is_liar) or (suspect != scenario and not is_liar):
                    return False
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for person, stmts in statements.items():
        for statement in stmts:
            # Ignore statements about the day of the week
            if any(day in statement for day in days_of_week):
                continue

            # Check if the statement is about guilt
            if "guilty" in statement:
                # Determine if the statement is a claim by the person or about the person
                if statement == "I am guilty.":
                    if (person in liar_count) != (person == scenario):
                        return False
                elif f"{scenario} is guilty." in statement:
                    if (person in liar_count) != (scenario == scenario):
                        return False
                elif f"{scenario} is not guilty." in statement:
                    if (person in liar_count) != (scenario != scenario):
                        return False
                elif " is guilty." in statement:
                    # Extract the name from the statement
                    accuser, _ = statement.split(" is guilty.", 1)
                    accuser = accuser.strip()
                    if (person in liar_count) != (accuser == scenario):
                        return False
                elif " is not guilty." in statement:
                    # Extract the name from the statement
                    accuser, _ = statement.split(" is not guilty.", 1)
                    accuser = accuser.strip()
                    if (person in liar_count) != (accuser != scenario):
                        return False
    return True

