    # Initialize a DP table where dp[i][j] represents the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # There's one way to arrange 0 pots with 0 types of flowers

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]  # Start with the number of ways without using the ith type of flower
            for k in range(1, a[i - 1] + 1):
                if j >= k:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD
                else:
                    break

    return dp[n][m]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i] will store the number of ways to arrange i pots
    dp = [0] * (m + 1)
    dp[0] = 1  # One way to arrange 0 pots: choose no pots at all

    for i in range(n):
        for j in range(m, -1, -1):
            for k in range(1, min(a[i], j) + 1):
                dp[j] = (dp[j] + dp[j - k]) % MOD

    return dp[m]

