    if n == 0:
        return 0

    # Initialize LIS and LDS arrays
    lis = [1] * n  # Longest Increasing Subsequence ending at each index
    lds = [1] * n  # Longest Decreasing Subsequence starting at each index

    # Fill LIS array
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Fill LDS array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Calculate the maximum length of a valid choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, lis[i] + lds[i] - 1)

    # The minimum number of students to leave is the total number of students
    # minus the maximum number that can form a valid choir
    return n - max_choir_length

